const agentItem = $('Agente Principal').first();
const native    = agentItem.metadata?.tokenUsage ?? {};

// El output final del agente está en el JSON (puede traer markdown fences)
const raw   = agentItem.json.output ?? '';
const clean = raw.replace(/^```json\\\\s*/i, '').replace(/\\\\s*```\\\\s*$/i, '').trim();

let parsed = {};
try { parsed = JSON.parse(clean); } catch { parsed = {}; }

const now = Date.now();
return {
  process_id:        $execution.id,
  model_name:        'gpt-5.1',
  prompt_tokens:     native.promptTokens     ?? 0,
  completion_tokens: native.completionTokens ?? 0,
  total_tokens:      native.totalTokens      ?? 0,
  ai_response:       parsed.replyText        ?? clean,
  completed_at:      now,
  created_at:        now,
  environment:       $('Convertir Entrada').item.json.environment ?? 'prod',
  token_source:      'native'
}

// 1. Obtenemos el texto del agente
let rawOutput = $('Agente Principal').item.json.output;
let data = {};

if (typeof rawOutput === 'string') {
    try {
        // Limpiamos el texto de espacios o saltos de línea al inicio/fin
        let cleanedOutput = rawOutput.trim();

        // Extraemos estrictamente lo que hay entre la primera '{' y la última '}'
        // Esto ignora comillas huérfanas al final (como el }") o formato markdown del LLM
        const jsonMatch = cleanedOutput.match(/\{[\s\S]*\}/);

        if (jsonMatch) {
            cleanedOutput = jsonMatch[0];
        }

        // Ahora sí, convertimos el texto limpio en un objeto
        data = JSON.parse(cleanedOutput);
    } catch (error) {
        // Si sigue fallando, evitamos que el flujo se rompa por completo
        console.error("Error al parsear el JSON:", error);
        data = {}; 
    }
} else {
    // Si ya venía como objeto, lo asignamos directamente
    data = rawOutput || {};
}

// 2. Obtenemos la lista plana de productos que viene en el input
let rawCatalog = [];
if (data.catalog){
  rawCatalog = Array.isArray(data.catalog) ? data.catalog : [data.catalog];
}

// 3. Retornamos el objeto final
return {
  replyText: data.replyText || "",
  sendImage: !!data.sendImage,
  imagenproducto: !!data.imagenproducto,
  categoria: data.categoria || "COCHES",
  catalog: rawCatalog
};

